-- Safe, user-scoped write policies for detection records generated by the web app.
-- Keep RLS enabled. Existing read policies remain unchanged.

create policy "Users can create their own events"
on public.detection_events
for insert
with check (
  auth.uid() = user_id
  and exists (
    select 1 from public.analysis_jobs j
    where j.id = job_id and j.user_id = auth.uid()
  )
);

create policy "Users can create their own incidents"
on public.incidents
for insert
with check (
  auth.uid() = user_id
  and exists (
    select 1 from public.analysis_jobs j
    where j.id = job_id and j.user_id = auth.uid()
  )
);
